package io.actrium.datastream

import io.actrium.actr.ActrException
import io.actrium.actr.dsl.ActrContext
import io.actrium.actr.dsl.RpcEnvelope
import io.actrium.datastream.proto.StartProbeRequest
import io.actrium.datastream.proto.StartProbeResponse

// 1:1 port of the GENERATED probe.actor.swift (ProbeServiceHandler protocol +
// ProbeServiceWorkload dispatcher). The Swift app has this generated by
// actr-cli; on Android we author the equivalent dispatch by hand since the
// Kotlin binding doesn't run actr-cli codegen.

/// Local ProbeService handler protocol (mirrors the generated Swift
/// `ProbeServiceHandler`). The RPC this actor serves:
///   local.ProbeService.StartProbe(StartProbeRequest) -> StartProbeResponse
interface ProbeServiceHandler {
    suspend fun startProbe(req: StartProbeRequest, ctx: ActrContext): StartProbeResponse
}

/// Dispatches incoming `local.ProbeService.StartProbe` RPCs to a handler.
/// Equivalent of the generated `ProbeServiceWorkload.__dispatch`.
class ProbeServiceWorkload<Handler : ProbeServiceHandler>(private val handler: Handler) {
    suspend fun dispatch(ctx: ActrContext, envelope: RpcEnvelope): ByteArray =
        when (envelope.routeKey) {
            ROUTE_START_PROBE -> {
                val req = StartProbeRequest.parseFrom(envelope.payload)
                val resp = handler.startProbe(req, ctx)
                resp.toByteArray()
            }
            else -> throw ActrException.UnknownRoute("Unknown route key: ${envelope.routeKey}")
        }

    companion object {
        const val ROUTE_START_PROBE = "local.ProbeService.StartProbe"
    }
}
